from pybricks.hubs import PrimeHub
from pybricks.parameters import Button, Color
from pybricks.tools import wait

# Set up.
prime_hub = PrimeHub()
Selected = 1

def Mission1():
    print('Mission1')
    prime_hub.light.on(Color.RED)
    wait(1000)

def Mission2():
    print('Mission2')
    prime_hub.light.on(Color.GREEN)
    wait(1000)

def Mission_3():
    print('Mission 3')
    prime_hub.light.on(Color.YELLOW)
    wait(1000)


# The main program starts here.
prime_hub.system.set_stop_button(Button.BLUETOOTH)
while True:
    prime_hub.display.number(Selected)
    if Button.RIGHT in prime_hub.buttons.pressed():
        Selected = Selected + 1
        wait(500)
    if Selected <= 1:
        Selected = 1
    if Button.LEFT in prime_hub.buttons.pressed():
        Selected = Selected - 1
        wait(500)
    if Button.CENTER in prime_hub.buttons.pressed():
        if Selected == 1:
            Mission1()
        if Selected == 2:
            Mission2()
        if Selected == 3:
            Mission_3()
        wait(1000)
